			ld d, (hl)
			ld (var_city_steer_pitch), de
			pop hl			; roll
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_city_steer_roll), de
			pop hl			; yaw
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_city_steer_yaw), de
			pop hl			; speed
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_city_steer_speed), de
			ld (p_city_steer_rs), sp
			ld sp, p_city_steer
			jp ntc_xn
